34: async function compileHtml(program) {
35:   const output = join(dirname(program), `${basename(program, '.co')}.html`);
36:   const [template, host, browserAssets, swiplAssets, swipl, session, runner, runtime, source] = await Promise.all([
37:     readFile(join(here, 'space-app.html'), 'utf8'),
38:     readFile(join(here, 'space-canvas-host.js'), 'utf8'),
39:     readFile(join(here, 'cosmos-browser-assets.js'), 'utf8'),
40:     readFile(join(here, 'cosmos-swipl-assets.js'), 'utf8'),
41:     readFile(join(here, 'prolog-wasm/swipl-bundle.js'), 'utf8'),
42:     readFile(join(here, 'cosmos-swipl-session.js'), 'utf8'),
43:     readFile(join(here, 'cosmos-space-runner.js'), 'utf8'),
44:     readFile(join(here, 'space-app.js'), 'utf8'),
45:     readFile(program, 'utf8')
46:   ]);
47:   const app = { name: basename(program), source };
48:   const serializedApp = JSON.stringify(app).replace(/</g, '\\u003c');
49:   // HTML treats script bodies as raw text and terminates them at any literal
50:   // </script>, even when that sequence occurs inside an embedded JS string.
51:   // The SWI bundle contains arbitrary payload text, so escape every such
52:   // sequence while preserving the JavaScript string's runtime value.
53:   const inlineScript = text => text.replace(/<\/script/gi, '<\\/script');
54:   const scripts = new Map([
55:     ['space-canvas-host.js', host],
56:     ['cosmos-browser-assets.js', browserAssets],
57:     ['cosmos-swipl-assets.js', swiplAssets],
58:     ['prolog-wasm/swipl-bundle.js', swipl],
59:     ['cosmos-swipl-session.js', session],
60:     ['cosmos-space-runner.js', runner],
61:     ['space-app.js', `window.__SPACE_PROGRAM__ = ${serializedApp};\n${runtime}`]
62:   ]);
63:   // Replace against the untouched template in one pass. Sequential string
64:   // replacements can accidentally match template-like text stored inside the
65:   // SWI bundle and corrupt its embedded filesystem payload.
66:   const html = template.replace(/<script src="([^"]+)"><\/script>/g, (tag, sourcePath) => {
67:     const script = scripts.get(sourcePath);
68:     return script === undefined ? tag : `<script>\n${inlineScript(script)}\n</script>`;
69:   });
70:   await writeFile(output, html, 'utf8');
71:   console.log(`Compiled ${basename(program)} -> ${output}`);
72: }
