79:   } catch {
80:     throw new Error('Electron is not installed. Run npm.cmd install in canvas first.');
81:   }
82:   await new Promise((resolveRun, reject) => {
83:     const child = spawn(electron, [here, '--space', program], { stdio: 'inherit' });
84:     child.once('error', reject);
85:     child.once('exit', code => code === 0 ? resolveRun() : reject(new Error(`Space process exited with code ${code}.`)));
86:   });
87: }

