#!/usr/bin/env node
// Pack the checked-in Cosmos compiler artifacts for the HTML/Electron Canvas.
//
// The compiler build (compiler/build.mjs) owns the self-hosted .co -> .pl
// artifacts, the bootstrap verification and the manifest.  This script only
// turns those same artifacts into the two browser bundles the Canvas pages
// load, so the editor, Cosmos OS and single-file Space apps all execute the
// identical generated code:
//
//   cosmos-swipl-assets.js     window.CosmosSwiplAssets   (self-hosted session)
//   cosmos-browser-assets.js   window.CosmosBrowserAssets (runtime + libraries)
//
// Nothing here is program-specific: every .co program uses the same bundle.
// Usage: node canvas/build-assets.mjs
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const canvas = dirname(fileURLToPath(import.meta.url));
const root = resolve(canvas, '..');
const modules = ['parser', 'normalize', 'resolve', 'check', 'emit_prolog', 'compiler'];

// Keys are exact SWI-WASM filenames, so cosmos-swipl-session.js can write them
// without inferring a directory.  /compiler-generated/ is also the stage the
// session passes to compiler_session_compile/4.
const sessionFiles = {
  '/src/swi.pl': 'compiler/swi.pl',
  '/src/reif.pl': 'compiler/reif.pl',
  '/compiler-platform/driver.pl': 'compiler/platform/driver.pl',
  '/compiler-platform/runtime.pl': 'compiler/platform/runtime.pl',
  '/compiler-platform/terms.pl': 'compiler/platform/terms.pl',
  '/compiler-platform/codec.pl': 'compiler/platform/codec.pl',
  '/compiler-platform/session.pl': 'compiler/platform/session.pl',
  ...Object.fromEntries(modules.map(name => [`/compiler-generated/${name}.pl`, `compiler/generated/${name}.pl`]))
};

const encode = file => readFileSync(join(root, file)).toString('base64');

const compilerAssets = Object.fromEntries(Object.entries(sessionFiles).map(([key, file]) => [key, encode(file)]));
writeFileSync(join(canvas, 'cosmos-swipl-assets.js'),
  `window.CosmosSwiplAssets = Object.freeze(${JSON.stringify(compilerAssets, null, 2)});\n`);

// reif.pl travels next to swi.pl as the fallback copy.  ensure_loaded(reif)
// inside swi.pl prefers the SWI library and only falls back to the bundled
// file, so a library that already provides reif simply ignores it.
const libraries = readdirSync(join(root, 'libs')).filter(name => name.endsWith('.pl')).sort();
const browserAssets = {
  swiPlBase64: encode('compiler/swi.pl'),
  reifPlBase64: encode('compiler/reif.pl'),
  libraryPlBase64: Object.fromEntries(libraries.map(name => [name, encode(`libs/${name}`)]))
};
writeFileSync(join(canvas, 'cosmos-browser-assets.js'),
  `(function () {\n  window.CosmosBrowserAssets = ${JSON.stringify(browserAssets, null, 2)};\n})();\n`);

console.log(`Generated canvas/cosmos-swipl-assets.js from ${Object.keys(compilerAssets).length} runtime/compiler files.`);
console.log(`Generated canvas/cosmos-browser-assets.js from the runtime and ${libraries.length} library files.`);

