test('the SWI compiler boundary normalizes Windows line endings', async () => {
  const source = await readFile('canvas/cosmos-swipl-session.js', 'utf8');
  assert.match(source, /replace\(\/\\r\\n\?\/g, '\\n'\)/);
  assert.match(source, /async compile\(source\)[\s\S]*source = normalizeSource\(source\)/);
});

test('the compiler owns no host implementation, so an embedder supplies one', async () => {
  // runtime.pl is the single generic host boundary.  It must declare the hook
  // and call it, never satisfy it: a native launcher, the browser session and a
  // future visual editor each add their own cosmos_host_op/3 clauses.
  const runtime = await readFile('compiler/platform/runtime.pl', 'utf8');
  assert.match(runtime, /^% .*\n% .*\n% .*\n:- multifile cosmos_host_op\/3\./m);
  assert.match(runtime, /cosmos_host_call\(Operation,Args,Result\) :-[^\n]*cosmos_host_op\(/);

  // A clause body for the hook anywhere under compiler/ would mean the
  // compiler answers host calls on the embedder's behalf.
  const compilerDirectory = join('compiler', 'platform');
  for (const entry of await readdir(compilerDirectory, { withFileTypes: true })) {
    if (!entry.isFile() || !entry.name.endsWith('.pl')) continue;
    const source = await readFile(join(compilerDirectory, entry.name), 'utf8');
    assert.doesNotMatch(source, /^cosmos_host_op\(/m, `${entry.name} must not implement cosmos_host_op/3`);
  }
  for (const generated of ['compiler/generated', 'compiler/seed', 'compiler/stage1', 'compiler/stage2']) {
    for (const entry of await readdir(generated, { withFileTypes: true })) {
      if (!entry.isFile() || !entry.name.endsWith('.pl')) continue;
      const source = await readFile(join(generated, entry.name), 'utf8');
      assert.doesNotMatch(source, /^cosmos_host_op\(/m, `${generated}/${entry.name} must not implement cosmos_host_op/3`);
    }
  }

  // The embedder side is what actually satisfies the hook.
  const session = await readFile('canvas/cosmos-swipl-session.js', 'utf8');
  assert.match(session, /wasm-host\.pl/);
  assert.match(session, /^cosmos_host_op\(/m);
});

