// Directory creation has to be idempotent.  mkdirTree/1 already is, and
// plain mkdir/1 is not usable as a check here: this runtime's stat/lookupPath
// reject an existing directory with an errno-less error, so a mkdir/1
// existence check can fail even when the directory is there.
function mkdir(FS, path) {
  if (typeof FS.mkdirTree === 'function') { FS.mkdirTree(path); return; }
  try { FS.mkdir(path); } catch (error) {
    if (!/exist/i.test(error?.message || '')) throw error;
  }
}

